$appId=(int)($_GET['app']??$_POST['app']??0); $error='';$success='';$project=null;$application=null;$applications=[];$navigation=[];$widgets=[];$builds=[];$applicationExportAllowed=$licenseCanExport;$applicationExportReason='';
try{
 $admin=enterprise_pdo();enterprise_upgrade($admin);$s=$admin->prepare('SELECT * FROM projects WHERE id=? AND product_type=? LIMIT 1');$s->execute([$projectId,'dataform']);$project=$s->fetch();if(!$project)throw new RuntimeException('DataForm-Projekt wurde nicht gefunden.');$_SESSION['active_project_id']=$projectId;
 $env=enterprise_env(dirname(__DIR__,2).'/DataForm5-Core/.env');$pdo=enterprise_project_store_for_project($env,$project);ApplicationBuilder::ensureSchema($pdo);
 if($applicationExportAllowed){foreach($pdo->query('SELECT id,name FROM dataforms ORDER BY id')->fetchAll(PDO::FETCH_ASSOC) as $exportDf){try{$dfPolicy=\EasyIT\Enterprise\Licensing\EnterpriseDataFormPolicyBridge::policy(dirname(__DIR__,2),$pdo,$projectId,(int)$exportDf['id'],false);\EasyIT\Enterprise\Licensing\EnterpriseDataFormPolicyBridge::require($dfPolicy,'export.execute',false);}catch(Throwable $policyError){$applicationExportAllowed=false;$applicationExportReason='DataForm „'.(string)$exportDf['name'].'“ ist nicht für den Export freigegeben.';break;}}}
 if($_SERVER['REQUEST_METHOD']==='POST'){
  enterprise_check_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');
  if($action==='create_app'){$name=trim((string)($_POST['name']??''));if($name==='')throw new RuntimeException('Anwendungsname fehlt.');$slug=ApplicationBuilder::slug((string)($_POST['slug']??$name));$stmt=$pdo->prepare('INSERT INTO applications(project_id,name,slug,version,description,environment,created_by) VALUES(?,?,?,?,?,?,?)');$stmt->execute([$projectId,$name,$slug,trim((string)($_POST['version']??'1.0.0'))?:'1.0.0',trim((string)($_POST['description']??''))?:null,(string)($_POST['environment']??'development'),$user['id']??null]);$appId=(int)$pdo->lastInsertId();$success='Anwendung wurde angelegt.';}
  elseif($action==='add_nav'){$stmt=$pdo->prepare('INSERT INTO application_navigation(application_id,label,target_type,target_value,icon,role_name,position,is_visible) VALUES(?,?,?,?,?,?,?,1)');$stmt->execute([$appId,trim((string)$_POST['label']),(string)($_POST['target_type']??'dataform'),trim((string)($_POST['target_value']??''))?:null,trim((string)($_POST['icon']??''))?:null,trim((string)($_POST['role_name']??''))?:null,(int)($_POST['position']??10)]);$success='Navigationseintrag wurde gespeichert.';}
  elseif($action==='add_widget'){$cfg=['source'=>trim((string)($_POST['source']??''))];$stmt=$pdo->prepare('INSERT INTO application_dashboard(application_id,widget_type,title,configuration_json,position,width) VALUES(?,?,?,?,?,?)');$stmt->execute([$appId,(string)($_POST['widget_type']??'metric'),trim((string)$_POST['title']),json_encode($cfg,JSON_UNESCAPED_UNICODE), (int)($_POST['position']??10),(string)($_POST['width']??'50')]);$success='Dashboard-Widget wurde gespeichert.';}
  elseif($action==='delete_nav'){$pdo->prepare('DELETE FROM application_navigation WHERE id=? AND application_id=?')->execute([(int)$_POST['id'],$appId]);$success='Navigationseintrag wurde gelöscht.';}
  elseif($action==='delete_widget'){$pdo->prepare('DELETE FROM application_dashboard WHERE id=? AND application_id=?')->execute([(int)$_POST['id'],$appId]);$success='Widget wurde gelöscht.';}
  elseif($action==='build'){if(!$applicationExportAllowed){throw new RuntimeException($applicationExportReason!==''?$applicationExportReason:'Der Application-Build ist in der aktuellen Lizenz nicht freigegeben.');}$q=$pdo->prepare('SELECT * FROM applications WHERE id=? AND project_id=?');$q->execute([$appId,$projectId]);$application=$q->fetch();if(!$application)throw new RuntimeException('Anwendung wurde nicht gefunden.');$result=ApplicationBuilder::build($pdo,$application,$project,$user,dirname(__DIR__,2));header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.$result['filename'].'"');header('Content-Length: '.$result['size']);header('X-Checksum-SHA256: '.$result['sha256']);readfile($result['path']);exit;}
 }
 $applications=$pdo->prepare('SELECT * FROM applications WHERE project_id=? ORDER BY name');$applications->execute([$projectId]);$applications=$applications->fetchAll();if($appId<1&&$applications)$appId=(int)$applications[0]['id'];if($appId>0){$q=$pdo->prepare('SELECT * FROM applications WHERE id=? AND project_id=?');$q->execute([$appId,$projectId]);$application=$q->fetch();if($application){$q=$pdo->prepare('SELECT * FROM application_navigation WHERE application_id=? ORDER BY position,id');$q->execute([$appId]);$navigation=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM application_dashboard WHERE application_id=? ORDER BY position,id');$q->execute([$appId]);$widgets=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM application_builds WHERE application_id=? ORDER BY created_at DESC LIMIT 20');$q->execute([$appId]);$builds=$q->fetchAll();}}
}catch(Throwable $e){$error=$e->getMessage();}
ob_start();
